// NovuClient core client that connects all services
type NovuClient struct {
	eventApi  *lib.EventApi
	subscriberApi *lib.SubscriberApi
}

// NewClient create a new instance of the NovuClient
func NewClient(ctx context.Context, apiKey string, cfg *lib.Config) (*NovuClient, error) {
	backendURL, err := lib.NormalizeBackendURL(apiKey, cfg)
	if err != nil {
		return nil, err
	}

	httpClient := lib.DefaultClient
	if cfg != nil && cfg.HttpClient != nil {
		httpClient = cfg.HttpClient
	}

	eventApi := lib.NewEventApi(ctx, backendURL, httpClient)
	subscriberApi := lib.NewSubscriberApi(ctx, backendURL, httpClient, PackageVersion)

	return &NovuClient{
		eventApi:  eventApi,
		subscriberApi: subscriberApi,
	}, nil
}

// Send an event using the client with given context, event and logger
func (c *NovuClient) Send(ctx context.Context, event Event, rl ...Logger) error {
	return c.eventApi.Send(ctx, event, rl...)
}

